"use client";
/* Ants, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Ants(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("ants"); }, []);
  return React.createElement("piix-pal", { "pal": "ants", ...piixAttrs(props) });
}

export default Ants;
